//! RFC 854: the data stream is NVT ASCII with in-band commands introduced by IAC
//! (octet 255). IAC WILL / WONT / DO / DONT (251-254) take one option octet;
//! IAC SB (250) opens a subnegotiation that runs to IAC SE (240); every other
//! command is two octets. Option codes come from the IANA "Telnet Options"
//! registry. The stream is neither a field table nor a TLV region, so commands and
//! runs of text alike become items (DEVIATIONS T1).
//!
//! Generated by dev/protogen from dev/protogen/specs/telnet.toml. Field layouts
//! come from the RFC cited above; edit the spec, not this file.

use crate::field::FieldDesc;
use crate::proto::{ProtoDesc, ProtoId};

// protogen:hand begin
use crate::layers::text;
use crate::options::Item;

const IAC: u8 = 255;
const SE: u8 = 240;
const SB: u8 = 250;

fn command_name(c: u8) -> &'static str {
    match c {
        240 => "SE",
        241 => "NOP",
        242 => "DataMark",
        243 => "Break",
        244 => "InterruptProcess",
        245 => "AbortOutput",
        246 => "AreYouThere",
        247 => "EraseCharacter",
        248 => "EraseLine",
        249 => "GoAhead",
        251 => "WILL",
        252 => "WONT",
        253 => "DO",
        254 => "DONT",
        _ => "IAC",
    }
}

/// IANA "Telnet Options" registry.
fn option_name(o: u8) -> &'static str {
    match o {
        0 => "BinaryTransmission",
        1 => "Echo",
        3 => "SuppressGoAhead",
        5 => "Status",
        6 => "TimingMark",
        24 => "TerminalType",
        31 => "WindowSize",
        32 => "TerminalSpeed",
        33 => "RemoteFlowControl",
        34 => "Linemode",
        36 => "EnvironmentOption",
        39 => "NewEnvironment",
        _ => "Option",
    }
}

fn parse_options(hdr: &[u8]) -> Vec<Item> {
    let mut out = Vec::new();
    let mut i = 0usize;
    let mut run = 0usize;
    while i < hdr.len() && out.len() < 128 {
        if hdr[i] != IAC {
            i += 1;
            continue;
        }
        if i > run {
            out.push(text::named("data", &hdr[run..i]));
        }
        let cmd = hdr.get(i + 1).copied().unwrap_or(0);
        match cmd {
            251..=254 => {
                let opt = hdr.get(i + 2).copied().unwrap_or(0);
                out.push(text::item(
                    command_name(cmd),
                    opt as u32,
                    option_name(opt).as_bytes(),
                ));
                i += 3;
            }
            SB => {
                let end = hdr[i..]
                    .windows(2)
                    .position(|w| w[0] == IAC && w[1] == SE)
                    .map_or(hdr.len(), |p| i + p + 2);
                out.push(Item::bytes(
                    "SB",
                    hdr.get(i + 2).copied().unwrap_or(0) as u32,
                    hdr.get(i + 2..end).unwrap_or(&[]),
                ));
                i = end;
            }
            _ => {
                out.push(Item::flag(command_name(cmd), cmd as u32));
                i += 2;
            }
        }
        run = i;
    }
    if run < hdr.len() {
        out.push(text::named("data", &hdr[run..]));
    }
    out
}
// protogen:hand end

pub static FIELDS: &[FieldDesc] = &[FieldDesc::var_bytes_to_end("lines", 0)];

